import {newReference,openDialog} from './compat';
import './style.css';
import {api,ApiError,authenticate,initialiseToken,hasToken,forgetToken,API_URL} from './api';
import {capabilities,startRecording,stopRecording,cancelRecording,speak,stopSpeech} from './device';
