import type {Exam,Item,Answer,Answers,Attempt,Envelope,Result,Review,User,Access,Course,Card,Submission,Resource} from './types';

type Tab='home'|'practice'|'mocks'|'coaching'|'account';
const app=document.querySelector<HTMLDivElement>('#app')!;
const icons:Record<string,string>={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',practice:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4zM13 7a3 3 0 0 1 3-3h5v14h-5a3 3 0 0 0-3 3"/>',mocks:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v4H9zM8 11h8m-8 4h8"/>',coaching:'<path d="m9 6 10 6-10 6z"/><rect x="3" y="3" width="18" height="18" rx="5"/>',account:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',moon:'<path d="M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',spark:'<path d="m12 2 2.6 7.4L22 12l-7.4 2.6L12 22l-2.6-7.4L2 12l7.4-2.6z"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0"/><circle cx="12" cy="20" r="1"/>',check:'<path d="m5 12 4 4L19 6"/>',leaf:'<path d="M12 21V8m0 6C3 14 3 8 4 3c7 0 10 5 8 11m0-5c0-5 4-7 8-6 1 5-2 9-8 9"/>'};
const titles:Record<string,string>={'ielts-academic':'IELTS Academic','ielts-general':'IELTS General Training','pte-academic':'PTE Academic','pte-core':'PTE Core'};
let maxAudioBytes=10*1024*1024;
let tab:Tab='home',user:User|null=null,access:Access|null=null,courses:Course[]=[],onlineReady=false,connectionMessage='',active:Attempt|null=null,lastEnvelope:Envelope|null=null;
let selectedCourse=read('course','ielts-academic'),practiceMode:'offline'|'guided'|'generated'='offline',selectedSkill='all',search='',onlineCards:Card[]|null=null,generatedPage=1,generatedPages=1,authMode:'login'|'register'='login',busy=false,recordingItem:string|null=null;
const recordings=new Map<string,{base64:string;mime:'audio/wav';duration_seconds:number}>();
const feedbacks=new Map<string,Review>();
let clock:ReturnType<typeof setInterval>|null=null;
function h<K extends keyof HTMLElementTagNameMap>(tag:K,cls='',text?:string){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function icon(name:string){const n=h('span','icon');n.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;return n}
function button(label:string,action:()=>void|Promise<void>,cls='button'){const b=h('button',cls,label);b.type='button';b.addEventListener('click',()=>void action());return b}
function text(text:string,cls=''){return h('p',cls,text)}
function field(label:string,input:HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement){const l=h('label','field');l.append(h('span','field-label',label),input);return l}
function input(name:string,type='text',value=''){const n=h('input');n.name=name;n.type=type;n.value=value;return n}
function select(options:Record<string,string>,value:string){const s=h('select');for(const [id,title] of Object.entries(options)){const o=h('option','',title);o.value=id;o.selected=id===value;s.append(o)}return s}
function read(key:string,fallback=''){try{return localStorage.getItem(`nisha-mobile:${key}`)||fallback}catch{return fallback}}
function write(key:string,value:string){try{localStorage.setItem(`nisha-mobile:${key}`,value)}catch{announce('Device storage is unavailable. Keep this practice open to retain your work.')}}
function scope(){return user?`user-${user.id}`:'guest'}
function announce(value:string){document.querySelector('#announcer')!.textContent=value}
function errorText(error:unknown){return error instanceof Error?error.message:'Something interrupted this request. Your work is retained. Please try again.'}
function format(seconds:number){const s=Math.max(0,Math.ceil(seconds));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function words(v:string){return v.trim()?v.trim().split(/\s+/u).length:0}
function answered(v:Answer|undefined):boolean{return typeof v==='string'?Boolean(v.trim()):Array.isArray(v)?v.length>0:v?Object.values(v).some(Boolean):false}
function theme(){return document.documentElement.dataset.theme||'light'}
function setTheme(value:string){document.documentElement.dataset.theme=value;write('theme',value);document.querySelector('meta[name=theme-color]')?.setAttribute('content',value==='dark'?'#11251d':'#174f3c')}
function shell(){app.replaceChildren();const header=h('header','app-header');const brand=button('',()=>navigate('home'),'brand');brand.append(icon('leaf'),h('span','','NISHA.'));brand.setAttribute('aria-label','NISHA home');const controls=h('div','header-controls');const mode=button('',()=>{setTheme(theme()==='dark'?'light':'dark');render()},'icon-button');mode.id='theme-toggle';mode.setAttribute('aria-label',theme()==='dark'?'Use light mode':'Use dark mode');mode.append(icon(theme()==='dark'?'sun':'moon'));const account=button(user?user.name.slice(0,1).toUpperCase():'N',()=>navigate('account'),'avatar');account.setAttribute('aria-label',user?'My account':'Sign in');controls.append(mode,account);header.append(brand,controls);const main=h('main','app-main');main.id='main';const nav=h('nav','bottom-nav');nav.setAttribute('aria-label','Main navigation');for(const value of ['home','practice','mocks','coaching','account'] as Tab[]){const n=button('',()=>navigate(value),'nav-item'+(tab===value&&!active?' selected':''));n.dataset.tab=value;n.setAttribute('aria-label',value[0].toUpperCase()+value.slice(1));if(tab===value&&!active)n.setAttribute('aria-current','page');n.append(icon(value),h('span','',value==='mocks'?'Mock tests':value[0].toUpperCase()+value.slice(1)));nav.append(n)}app.append(header,main,nav);return main}
function heading(kicker:string,title:string,description?:string){const d=h('div','page-heading');d.append(text(kicker,'eyebrow'),h('h1','',title));if(description)d.append(text(description,'lead'));return d}
function notice(message:string,kind=''){const n=h('div',`notice ${kind}`,message);n.setAttribute('role','status');return n}
function panel(title:string,description?:string){const p=h('section','panel');p.append(h('h2','',title));if(description)p.append(text(description,'muted'));return p}
function discardMedia() {
  recordingItem=null;
  recordings.clear();
  void cancelRecording().catch(()=>{});
  void stopSpeech().catch(()=>{});
  document.querySelectorAll('video,audio').forEach(node=>(node as HTMLMediaElement).pause());
}
function navigate(next:Tab) {
  if(active){saveAttempt();active=null;stopClock()}
  discardMedia();
  if(tab!==next){onlineCards=null;if(next==='practice'&&practiceMode==='generated')practiceMode='offline'}
  tab=next;lastEnvelope=null;render();window.scrollTo(0,0);
  if(next==='mocks')void loadOnline();
}

function render(){if(active){renderRunner();return}const main=shell();if(lastEnvelope){renderResult(main,lastEnvelope);return}if(tab==='home')renderHome(main);if(tab==='practice')renderPractice(main);if(tab==='mocks')renderMocks(main);if(tab==='coaching'){main.append(heading('LEARN FROM A LITTLE GUIDANCE','A teacher in your corner.','Explore lessons made by NISHA teachers.'));void renderCoaching()}if(tab==='account')renderAccount(main)}
function resumeButton(){const saved=loadAttempt();if(!saved)return null;return button(`Resume ${saved.exam.session_type==='full'?'your mock':'your practice'} →`,()=>{active=saved;renderRunner();startClock()},'button outline')}
function renderHome(main:HTMLElement){const hero=h('section','home-hero');hero.append(text('YOUR NEXT CHAPTER, IN YOUR POCKET','eyebrow'),h('h1','','Big dreams.\nSmall, steady steps.'),text('Your IELTS & PTE practice, wherever life takes you.','hero-copy'));const badge=h('span','hero-spark');badge.append(icon('spark'));hero.append(badge);const cta=button('Find my next practice',()=>navigate('practice'),'button light');cta.append(icon('arrow'));hero.append(cta);main.append(hero);const welcome=h('div','section-heading');welcome.append(h('h2','',user?`Welcome back, ${user.name.split(' ')[0]}.`:'A little progress today?'),text('Make a few quiet minutes count.','muted'));main.append(welcome);const resume=resumeButton();if(resume)main.append(resume);const stats=h('div','quick-stats');stats.append(stat(String(offlineSessions.length),'offline practice tasks'),stat('4','IELTS & PTE courses'),stat(String(localHistory().length),'results on this phone'));main.append(stats);const choose=h('div','home-tiles');for(const [name,description,target,glyph] of [['Build a skill','One question. One useful lesson.','practice','practice'],['Try the full experience','Timed mocks, at your pace.','mocks','mocks'],['Learn with a teacher','Coaching that makes things click.','coaching','coaching']] as const){const b=button('',()=>navigate(target),'feature-tile');b.append(icon(glyph),h('strong','',name),text(description,'muted'),icon('arrow'));choose.append(b)}main.append(choose);const offline=h('section','offline-banner');offline.append(icon('wifi'),h('div'));offline.lastElementChild!.append(h('h2','','No connection? Keep going.'),text(`${offlineSessions.length} original generated practice tasks are included on your phone. No sign-in needed.`,'muted'));const go=button('Explore offline practice →',()=>{tab='practice';onlineCards=null;practiceMode='offline';render()},'text-button');go.dataset.action='offline';offline.lastElementChild!.append(go);main.append(offline);if(connectionMessage)main.append(notice(connectionMessage));main.append(text('Independent NISHA learning material. Practice points and AI feedback are guidance, not official IELTS bands or PTE scores.','fine-print'))}
function stat(value:string,label:string){const n=h('div','stat');n.append(h('strong','',value),h('span','',label));return n}
function courseFilters(onChange:()=>void){const form=h('form','filters');const course=select(titles,selectedCourse);course.id='practice-course';course.onchange=()=>{selectedCourse=course.value;write('course',selectedCourse);onlineCards=null;generatedPage=1;onChange()};const skill=select({all:'All skills',reading:'Reading',listening:'Listening',writing:'Writing',speaking:'Speaking'},selectedSkill);skill.id='practice-skill';skill.onchange=()=>{selectedSkill=skill.value;onlineCards=null;generatedPage=1;onChange()};const query=input('search','search',search);query.id='practice-search';query.placeholder='Find a topic or question type';query.maxLength=100;form.append(field('Your course',course),field('Focus on',skill),field('Search practice',query));form.onsubmit=e=>{e.preventDefault();search=query.value.trim();onChange()};query.onchange=()=>{search=query.value.trim();onChange()};return form}
function renderPractice(main:HTMLElement){main.append(heading('ONE QUESTION. ONE STEP FORWARD.','Make room for practice.','Choose a skill, settle in and learn something useful.'));main.append(courseFilters(()=>{if(practiceMode==='generated')void loadGenerated('questions');else render()}));const modes=h('div','segmented');modes.append(button('On this phone',()=>{practiceMode='offline';onlineCards=null;render()},'segment'+(practiceMode==='offline'?' active':'')),button('Question types',()=>{practiceMode='guided';render();void loadOnline()},'segment'+(practiceMode==='guided'?' active':'')),button('Generated library',()=>void loadGenerated('questions'),'segment'+(practiceMode==='generated'?' active':'')));main.append(modes);if(connectionMessage)main.append(notice(connectionMessage));if(practiceMode==='offline'){const matches=listOffline({course:selectedCourse,skill:selectedSkill==='all'?undefined:selectedSkill,query:search});main.append(text(`${matches.length} offline tasks · Generated, not teacher-reviewed`,'results-count'));const grid=h('div','card-list');for(const exam of matches){const item=exam.sections[0].items[0];const card=makeCard({id:exam.id,name:item.task_type||exam.name,skill:String(exam.sections[0].id).replace('generated-',''),item_count:1},()=>startSession(exam.id,true));card.append(text(item.title||exam.description||'Original NISHA practice','muted'));grid.append(card)}if(!matches.length)grid.append(notice('No tasks match this focus. Try another skill or clear your search.'));main.append(grid)}else if(practiceMode==='guided'){const modules=courses.find(c=>c.id===selectedCourse)?.modules||[];const visible=modules.filter(m=>(selectedSkill==='all'||m.skill===selectedSkill)&&(!search||m.title.toLowerCase().includes(search.toLowerCase())));const grid=h('div','card-list');for(const m of visible)grid.append(makeCard({id:m.practice_id,name:m.title,skill:m.skill,item_count:m.item_count},()=>startSession(m.practice_id,false)));if(!visible.length)grid.append(notice(onlineReady?'No question types match this focus. Try another skill or search.':'Connect to NISHA to load the current question-type library. Included offline practice is ready.'));main.append(text(`${visible.length} guided question types`,'results-count'),grid)}else renderCards(main,onlineCards||[],false);main.append(text('Offline tasks are generated learning variations. Related tasks and assembled mocks may reuse scenarios. Written and spoken answers can be practised offline; AI coaching needs a connection and sign-in.','fine-print'))}
function makeCard(card:Card,action:()=>void|Promise<void>){const n=h('article','practice-card');const top=h('div','card-top');top.append(text((card.skill||'practice').replaceAll('-',' '),'eyebrow'),h('span','pill',card.session_type==='full'?'Timed mock':`${card.item_count||1} tasks`));n.append(top,h('h3','',card.name));if(card.duration_seconds)n.append(text(`${Math.ceil(card.duration_seconds/60)} minutes · Practice guidance`,'muted'));const b=button(card.session_type==='full'?'Open this mock →':'Start practice →',action,'text-button');b.dataset.sessionId=card.id;n.append(b);return n}
function renderCards(main:HTMLElement,cards:Card[],mocks:boolean){const grid=h('div','card-list');for(const c of cards.filter(x=>!search||x.name.toLowerCase().includes(search.toLowerCase())))grid.append(makeCard(c,()=>startSession(c.id,false)));if(!cards.length)grid.append(notice(mocks?'No mocks are available for this course yet.':'No online questions match these filters.'));main.append(grid);if(generatedPages>1){const paging=h('div','pagination');const prev=button('← Previous',()=>{generatedPage--;void loadGenerated(mocks?'mocks':'questions')},'button outline');prev.disabled=generatedPage<=1;const next=button('Next →',()=>{generatedPage++;void loadGenerated(mocks?'mocks':'questions')},'button outline');next.disabled=generatedPage>=generatedPages;paging.append(prev,text(`${generatedPage} / ${generatedPages}`),next);main.append(paging)}}
async function loadGenerated(kind:'questions'|'mocks'){if(busy)return;busy=true;announce('Opening the online library.');try{const reply=await api<any>('generated',{course:selectedCourse,kind,page:generatedPage,skill:selectedSkill});onlineCards=reply.items||reply.catalog?.items||[];generatedPages=reply.pages||reply.catalog?.pages||1;connectionMessage='';onlineReady=true;tab=kind==='mocks'?'mocks':'practice';if(kind==='questions')practiceMode='generated';render()}catch(e){connectionMessage=errorText(e);onlineCards=null;if(kind==='questions')practiceMode='offline';render()}finally{busy=false}}
async function loadOnline(refresh=true){try{const reply=await api<any>('catalog');courses=reply.courses||[];const cap=reply.ai?.maxAudioBytes;maxAudioBytes=typeof cap==='number'&&Number.isFinite(cap)?Math.max(0,Math.min(10*1024*1024,Math.floor(cap))):10*1024*1024;onlineReady=true;connectionMessage='';if(refresh)render()}catch(e){onlineReady=false;connectionMessage=errorText(e);if(refresh)render()}}
function renderMocks(main:HTMLElement){main.append(heading('A LITTLE CLOSER TO TEST DAY','The full experience.','Work through a timed IELTS or PTE mock on your phone. A quiet place and headphones can help.'));const c=select(titles,selectedCourse);c.id='mock-course';c.onchange=()=>{selectedCourse=c.value;write('course',selectedCourse);onlineCards=null;render()};main.append(field('Choose your course',c));if(!user)main.append(notice('Sign in to use your first free full mock. Guided and offline practice are available now.'));else if(access?.paid_active)main.append(notice(`Your full mock access is active${access.paid_until?` until ${access.paid_until} UTC`:''}.`));else main.append(notice(access?.trial_state==='consumed'?'Your free full mock is complete. This app can use an existing active NISHA access pass. Offline and guided practice remain available.':'One completed full mock is free with your account. Your free allowance is shared across IELTS and PTE.'));const course=courses.find(x=>x.id===selectedCourse);const base=course?.full_exam_id||({'ielts-academic':'ielts-academic-01','ielts-general':'ielts-general-01','pte-academic':'pte-academic-01','pte-core':'pte-core-01'}[selectedCourse])||'ielts-academic-01';main.append(makeCard({id:base,name:`${titles[selectedCourse]} · Original full mock`,session_type:'full',duration_seconds:selectedCourse.startsWith('ielts')?9840:selectedCourse==='pte-academic'?8400:7200},()=>startSession(base,false)));if(course){const parts=h('section','panel');parts.append(h('h2','','A shorter rehearsal'));for(const section of course.sections)parts.append(makeCard({id:section.exam_id,name:section.title,item_count:section.item_count,duration_seconds:section.duration_seconds,session_type:'section'},()=>startSession(section.exam_id,false)));main.append(parts)}main.append(button('Explore generated mock variants →',()=>void loadGenerated('mocks'),'button outline'));if(onlineCards!==null)renderCards(main,onlineCards,true);if(connectionMessage)main.append(notice(connectionMessage));main.append(text('Full mocks need an internet connection to reserve access and save results. Timers continue when the app is in the background. Recordings are not restored after closing the app.','fine-print'))}
async function startSession(id:string,offline:boolean){if(busy)return;busy=true;try{let exam:Exam;if(offline){const local=getOffline(id);if(!local)throw new Error('This offline task is unavailable. Please choose another.');exam=local}else{const reply=await api<{exam:Exam}>('content',{id});exam=reply.exam}const attemptId=newReference();if(exam.requires_access||(exam.session_type||'full')==='full'){if(!user){tab='account';render();toast('Sign in to start your full mock.');return}if(!await confirmDialog('Ready for a timed mock?','The clock will continue when you leave or reload. Your answers stay on this phone; recordings are kept only while this app stays open.','Begin mock'))return;const reply=await api<any>('start_mock',{exam_id:id,attempt_id:attemptId},'POST');exam=reply.exam;access=reply.access||access}active={exam,id:attemptId,answers:{},sectionIndex:0,itemIndex:0,startedAt:Date.now(),sectionDeadline:Date.now()+exam.sections[0].duration_seconds*1000,completed:[],offline,assisted:false,scope:scope(),expiresAt:Date.now()+48*3600*1000,itemDeadlines:{}};lastEnvelope=null;saveAttempt();renderRunner();startClock();window.scrollTo(0,0)}catch(e){toast(errorText(e))}finally{busy=false}}
function saveAttempt(){if(active){write(`attempt:${active.scope}`,JSON.stringify(active));write(`active:${active.scope}`,'1')}}
function loadAttempt():Attempt|null{try{const a=JSON.parse(read(`attempt:${scope()}`,'null'));if(a&&a.scope===scope()&&a.expiresAt>Date.now()&&a.exam?.sections?.[a.sectionIndex]?.items?.[a.itemIndex])return a}catch{}return null}
function stopClock(){if(clock)clearInterval(clock);clock=null}
function startClock(){stopClock();clock=setInterval(()=>{if(!active)return;updateClocks();if(active.exam.timing_mode!=='untimed'&&Date.now()>=active.sectionDeadline)void nextSection(true)},1000)}
function currentItem(){return active!.exam.sections[active!.sectionIndex].items[active!.itemIndex]}
function updateAnswer(value:Answer){if(!active)return;active.answers[currentItem().id]=value;feedbacks.delete(`${active.id}:${currentItem().id}`);saveAttempt()}
function updateClocks(){if(!active)return;const section=document.querySelector('#section-clock');if(section)section.textContent=active.exam.timing_mode==='untimed'?'At your pace':format((active.sectionDeadline-Date.now())/1000);const item=document.querySelector('#item-clock');if(item){const d=active.itemDeadlines[currentItem().id];if(d)item.textContent=Date.now()<d.prep?`Prepare · ${format((d.prep-Date.now())/1000)}`:`Respond · ${format((d.end-Date.now())/1000)}`}}
function renderRunner(){if(!active)return;const a=active;const s=a.exam.sections[a.sectionIndex];const q=currentItem();const main=shell();main.id='runner';const back=button('← Save & leave',()=>{saveAttempt();active=null;stopClock();discardMedia();render()},'text-button');main.append(back);const top=h('div','runner-heading');top.append(text(a.exam.name,'eyebrow'),h('h1','',s.title));const timer=h('strong','timer');timer.id='section-clock';timer.setAttribute('role','timer');top.append(timer);main.append(top);const count=h('div','progress-caption');count.append(text(`Section ${a.sectionIndex+1} of ${a.exam.sections.length}`),text(`Task ${a.itemIndex+1} of ${s.items.length}`));main.append(count);const progress=h('div','progress-track');const bar=h('span');bar.style.width=`${100*(a.itemIndex+1)/s.items.length}%`;progress.append(bar);main.append(progress);if(a.offline||a.exam.content_source==='generated'||a.exam.generated)main.append(notice('Generated practice · Not teacher-reviewed. Related tasks and mocks reuse scenarios.'));if(a.exam.timing_mode!=='untimed'){const assist=button(a.assisted?'Assisted mode enabled':'Enable transcripts & replay',()=>{if(active){active.assisted=true;saveAttempt();renderRunner()}},'text-button');main.append(assist)}main.append(text(s.instructions||'Follow the instructions and use the supplied evidence.','muted'));const question=h('section','question-panel');question.append(text(q.task_type||q.type,'eyebrow'),h('h2','',q.prompt||q.title||'Your next task'));if(q.instructions)question.append(text(q.instructions));if(q.cues){const cues=h('ul','cues');q.cues.forEach(c=>cues.append(h('li','',c)));question.append(cues)}if(q.resource_id&&a.exam.resources[q.resource_id])question.append(renderResource(a.exam.resources[q.resource_id],a));if(q.secondary_resource_id&&a.exam.resources[q.secondary_resource_id])question.append(renderResource(a.exam.resources[q.secondary_resource_id],a));if(a.exam.timing_mode!=='untimed'&&q.type==='spoken'&&(q.prep_seconds||q.response_seconds)){if(!a.itemDeadlines[q.id])a.itemDeadlines[q.id]={prep:Date.now()+(q.prep_seconds||0)*1000,end:Date.now()+((q.prep_seconds||0)+(q.response_seconds||60))*1000};saveAttempt();const timer=h('p','item-timer');timer.id='item-clock';question.append(timer)}const controls=h('div','answer-controls');controls.id='answer-controls';renderAnswer(q,controls,a.answers[q.id]);question.append(controls);if(a.exam.session_type==='practice'){const check=button(['essay','spoken'].includes(q.type)?'Show review checklist':'Check my answer',()=>void checkAnswer(),'button outline');check.id='check-answer';question.append(check);const feedback=feedbacks.get(`${a.id}:${q.id}`);if(feedback)question.append(feedbackPanel(feedback));if(['essay','spoken'].includes(q.type))question.append(aiPanel(q,a))}main.append(question);const actions=h('div','runner-actions');const previous=button('← Previous',()=>move(-1),'button outline');previous.disabled=a.itemIndex===0;previous.hidden=s.navigation==='forward';const next=button(a.itemIndex<s.items.length-1?'Next task →':a.sectionIndex<a.exam.sections.length-1?'Next section →':'Finish & review →',()=>void move(1),'button');next.id='next-item';actions.append(previous,next);main.append(actions);if(s.navigation!=='forward'){const map=h('div','question-map');s.items.forEach((item,i)=>{const b=button(String(i+1),()=>{if(active){active.itemIndex=i;saveAttempt();renderRunner()}},'map-button'+(answered(a.answers[item.id])?' answered':'')+(i===a.itemIndex?' current':''));b.setAttribute('aria-label',`Task ${i+1}${answered(a.answers[item.id])?', response entered':''}`);map.append(b)});main.append(map)}const finish=button(a.exam.session_type==='practice'?'Finish practice':'Submit test early',()=>void submitAttempt(false),'text-button');finish.id='finish-practice';main.append(finish,text('Your text answers are saved on this device for 48 hours, separately for each account. Audio stays on this phone unless you explicitly request AI review.','fine-print'));updateClocks()}
function renderResource(r:Resource,a:Attempt){const d=h('section','resource');if(r.title)d.append(h('h3','',r.title));if(r.kind==='audio'){const played=new Set((a as Attempt&{played?:string[]}).played||[]);const key=r.title||r.audio_script||'audio';const listen=button('▶ Listen',async()=>{if(!r.audio_script)return;try{await speak(r.audio_script);played.add(key);(a as Attempt&{played?:string[]}).played=[...played];saveAttempt();if(a.exam.timing_mode!=='untimed'&&!a.assisted)listen.disabled=true}catch(e){toast(errorText(e))}},'button outline');listen.disabled=a.exam.timing_mode!=='untimed'&&!a.assisted&&played.has(key);d.append(listen,button('Stop audio',()=>stopSpeech(),'text-button'));if(a.exam.session_type==='practice'||a.assisted){const transcript=h('details','transcript');transcript.append(h('summary','','Read transcript'),text(r.audio_script||''));d.append(transcript)}d.append(text('Listening uses your device’s English speech voice. Voice availability varies.','fine-print'))}else if(r.kind==='chart'&&r.chart){d.append(renderChart(r.chart));if(r.description)d.append(text(r.description,'fine-print'))}else if(r.kind==='table'){const table=h('table','resource-table');const thead=h('thead'),head=h('tr');(r.columns||[]).forEach(c=>head.append(h('th','',String(c))));thead.append(head);table.append(thead);const body=h('tbody');(r.rows||[]).forEach(row=>{const tr=h('tr');row.forEach(c=>tr.append(h('td','',String(c))));body.append(tr)});table.append(body);const wrap=h('div','table-scroll');wrap.append(table);d.append(wrap)}else{(r.paragraphs||[]).forEach(p=>d.append(text(p)));if(r.description)d.append(text(r.description));if(!r.paragraphs?.length&&r.kind==='diagram'){const diagram=r.diagram as Record<string,unknown>|undefined;if(diagram){d.append(renderDiagram(diagram));if(typeof diagram.description==='string')d.append(text(diagram.description,'fine-print'))}}if(r.audio_script&&a.assisted)d.append(text(r.audio_script))}return d}
function renderDiagram(diagram:Record<string,unknown>) {
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 100 100');svg.setAttribute('class','resource-diagram');svg.setAttribute('role','img');svg.setAttribute('aria-label',String(diagram.description||'Question diagram'));
  const nodes=Array.isArray(diagram.nodes)?diagram.nodes as Record<string,unknown>[]:[];
  const edges=Array.isArray(diagram.edges)?diagram.edges as Record<string,unknown>[]:[];
  const number=(value:unknown,fallback=0)=>typeof value==='number'&&Number.isFinite(value)?Math.max(0,Math.min(100,value)):fallback;
  for(const edge of edges){const from=nodes.find(node=>node.id===edge.from),to=nodes.find(node=>node.id===edge.to);if(!from||!to)continue;const line=document.createElementNS(svg.namespaceURI,'line');for(const [key,value]of Object.entries({x1:number(from.x)+number(from.width,20)/2,y1:number(from.y)+number(from.height,12)/2,x2:number(to.x)+number(to.width,20)/2,y2:number(to.y)+number(to.height,12)/2}))line.setAttribute(key,String(value));svg.append(line)}
  for(const node of nodes){const x=number(node.x),y=number(node.y),width=number(node.width,20),height=number(node.height,12);const rect=document.createElementNS(svg.namespaceURI,'rect');for(const [key,value]of Object.entries({x,y,width,height,rx:2}))rect.setAttribute(key,String(value));const label=document.createElementNS(svg.namespaceURI,'text');label.setAttribute('x',String(x+width/2));label.setAttribute('y',String(y+height/2+1.5));label.setAttribute('text-anchor','middle');label.setAttribute('font-size','4');label.textContent=String(node.label||'');svg.append(rect,label)}
  return svg;
}
function renderChart(c:NonNullable<Resource['chart']>){const wrap=h('div','chart');const cats=c.categories||[];const series=c.series||[];if(c.unit)wrap.append(text(c.unit,'fine-print'));const max=Math.max(1,...series.flatMap(x=>x.values));series.forEach(serie=>{wrap.append(h('h4','',serie.name));serie.values.forEach((value,i)=>{const row=h('div','chart-row');row.append(h('span','',cats[i]||String(i+1)));const bar=h('div','chart-bar');bar.style.width=`${Math.max(2,100*value/max)}%`;bar.append(h('strong','',String(value)));row.append(bar);wrap.append(row)})});return wrap}
function renderAnswer(q:Item,container:HTMLElement,response:Answer|undefined){if(q.type==='choice'||q.type==='multi'){const set=h('fieldset','choices');set.append(h('legend','sr-only',q.type==='multi'?'Select your answers':'Choose one answer'));(q.options||[]).forEach((o,i)=>{const label=h('label','choice');const n=input(q.id,q.type==='multi'?'checkbox':'radio',o.id);n.checked=q.type==='multi'?Array.isArray(response)&&response.includes(o.id):response===o.id;label.classList.toggle('selected',n.checked);n.onchange=()=>{let value:Answer=n.value;if(q.type==='multi'){const chosen=[...set.querySelectorAll<HTMLInputElement>('input:checked')];if(q.select_count&&chosen.length>q.select_count){n.checked=false;announce(`Choose at most ${q.select_count} answers.`);return}value=chosen.map(x=>x.value)}updateAnswer(value);set.querySelectorAll('label').forEach(l=>l.classList.toggle('selected',l.querySelector('input')!.checked))};label.append(n,h('span','choice-letter',String.fromCharCode(65+i)),h('span','',o.text));set.append(label)});container.append(set)}else if(q.type==='gaps'){const p=h('div','gap-text');const blanks=new Map((q.blanks||[]).map(b=>[b.id,b]));String(q.text||'').split(/(\{\{[^}]+\}\}|\[[^\]]+\])/u).forEach(piece=>{const match=piece.match(/^(?:\{\{([^}]+)\}\}|\[([^\]]+)\])$/u);const blank=match?blanks.get(match[1]||match[2]):undefined;if(!blank){p.append(document.createTextNode(piece));return}const value=typeof response==='object'&&!Array.isArray(response)?response[blank.id]||'':'';const n=blank.options?select({'':'Choose…',...Object.fromEntries(blank.options.map(v=>[v,v]))},value):input(blank.id,'text',value);n.setAttribute('aria-label',`Blank ${blank.id}`);n.oninput=()=>{const current=active!.answers[q.id];const next=typeof current==='object'&&!Array.isArray(current)?{...current}:{};next[blank.id]=n.value;updateAnswer(next)};n.onchange=n.oninput;p.append(n)});container.append(p)}else if(q.type==='reorder'){const order=Array.isArray(response)?response:(q.options||[]).map(x=>x.id);const list=h('ol','reorder-list');order.forEach((id,i)=>{const row=h('li');row.append(text(q.options?.find(o=>o.id===id)?.text||id));const actions=h('div','reorder-actions');for(const direction of [-1,1]){const b=button(direction<0?'↑ Move up':'↓ Move down',()=>{const next=[...order];[next[i],next[i+direction]]=[next[i+direction],next[i]];updateAnswer(next);container.replaceChildren();renderAnswer(q,container,next)},'button compact outline');b.disabled=i+direction<0||i+direction>=order.length;actions.append(b)}row.append(actions);list.append(row)});container.append(list,button('Confirm this order',()=>{updateAnswer([...order]);toast('Paragraph order entered.')},'button outline'))}else if(q.type==='highlight'){const words=h('div','highlight-words');const chosen=new Set(Array.isArray(response)?response:[]);String(q.text||'').split(/\s+/u).forEach((word,i)=>{const b=button(word,()=>{const id=String(i);if(chosen.has(id))chosen.delete(id);else chosen.add(id);b.classList.toggle('selected',chosen.has(id));b.setAttribute('aria-pressed',String(chosen.has(id)));updateAnswer([...chosen])},'word-button'+(chosen.has(String(i))?' selected':''));b.setAttribute('aria-pressed',String(chosen.has(String(i))));words.append(b)});container.append(words)}else if(q.type==='short'){const n=input(q.id,'text',typeof response==='string'?response:'');n.maxLength=2000;n.autocomplete='off';n.oninput=()=>updateAnswer(n.value);container.append(field('Your answer',n));if(q.max_words)container.append(text(`Use at most ${q.max_words} words.`,'fine-print'))}else if(q.type==='essay'||q.type==='spoken'){if(q.type==='spoken'){const b=button(recordingItem===q.id?'Stop recording ■':'Record my response ●',()=>void record(q,container),'button outline');b.disabled=!capabilities().recording;b.dataset.record=q.id;container.append(b,text('Recording is optional. Use a transcript of what you said for language feedback; pronunciation and delivery are not scored.','fine-print'));const clip=recordings.get(`${active!.id}:${q.id}`);if(clip){const audio=h('audio');audio.controls=true;audio.src=`data:audio/wav;base64,${clip.base64}`;container.append(audio,text(`${Math.round(clip.duration_seconds)} seconds · Kept only while this app stays open.`,'fine-print'))}}const area=h('textarea');area.rows=q.type==='essay'?10:4;area.maxLength=q.type==='essay'?50000:10000;area.value=typeof response==='string'?response:'';area.placeholder=q.type==='essay'?'Give your ideas a little room…':'Write exactly what you said, or leave this blank to use your recording.';const count=text(`${words(area.value)} words`,'word-count');area.oninput=()=>{updateAnswer(area.value);count.textContent=`${words(area.value)} words`};container.append(field(q.type==='essay'?'Your written response':'Transcript of what I said',area),count);if(q.min_words||q.max_words)container.append(text(`Task guide: ${q.min_words||0}${q.max_words?`–${q.max_words}`:' or more'} words.`,'fine-print'))}else container.append(notice('This task format needs the updated online exam room. Please choose another task.'))}
async function record(q:Item,container:HTMLElement) {
  const attempt=active;
  if(!attempt)return;
  try {
    if(recordingItem===q.id){
      const clip=await stopRecording();recordingItem=null;
      if(active!==attempt)return;
      recordings.set(`${attempt.id}:${q.id}`,clip);renderRunner();
    }else{
      if(recordingItem)await cancelRecording();
      await startRecording();
      if(active!==attempt||currentItem().id!==q.id){await cancelRecording();return}
      recordingItem=q.id;
      container.querySelector(`[data-record="${q.id}"]`)!.textContent='Stop recording ■';
      announce('Recording started. Stop when you finish your answer.');
    }
  }catch(e){recordingItem=null;toast(errorText(e))}
}

async function checkAnswer(){if(!active)return;const a=active,q=currentItem(),response=a.answers[q.id]??(['gaps'].includes(q.type)?{}:['multi','reorder','highlight'].includes(q.type)?[]:'');try{const review=a.offline?offlineFeedback(a.exam,q,response):(await api<any>('feedback',{exam_id:a.exam.id,exam_version:a.exam.version,item_id:q.id,response},'POST')).review;feedbacks.set(`${a.id}:${q.id}`,review);renderRunner();announce('Your feedback is ready.')}catch(e){toast(errorText(e))}}
function feedbackPanel(review:Review){const p=h('section','feedback-panel');const score=review.score===null?'Writing & speaking practice':review.score!==(0)?'Good progress — check the explanation.':'A useful moment to learn.';p.append(h('h3','',score));if(review.explanation)p.append(text(review.explanation));const correct=review.correct_answer??review.correct;if(correct!==undefined&&correct!==null)p.append(text(`Accepted answer: ${displayAnswer(correct)}`));if(review.rubric?.length){const list=h('ul');review.rubric.forEach(c=>list.append(h('li','',c)));p.append(list)}return p}
function displayAnswer(value:unknown):string{if(value===null||value===undefined)return 'No response';if(typeof value==='string'||typeof value==='number')return String(value);if(Array.isArray(value))return value.map(displayAnswer).join(' · ');return Object.entries(value as Record<string,unknown>).map(([k,v])=>`${k}: ${displayAnswer(v)}`).join('; ')}
async function move(direction:number){if(!active)return;await stopSpeech();if(recordingItem){toast('Stop your recording before moving to another task.');return}const s=active.exam.sections[active.sectionIndex];if(direction<0&&s.navigation==='forward')return;if(active.itemIndex+direction<s.items.length&&active.itemIndex+direction>=0){active.itemIndex+=direction;saveAttempt();renderRunner();window.scrollTo(0,0)}else if(direction>0)await nextSection(false)}
async function nextSection(expired:boolean) {
  if(!active||busy)return;
  if(!expired&&!await confirmDialog('Finish this section?','You can continue to the next section. In a timed test you cannot return to an earlier section.','Continue'))return;
  if(!active)return;
  const a=active;
  if(expired&&recordingItem){await cancelRecording().catch(()=>{});recordingItem=null}
  do {
    const part=a.exam.sections[a.sectionIndex];
    if(!a.completed.includes(part.id))a.completed.push(part.id);
    if(a.sectionIndex>=a.exam.sections.length-1){await submitAttempt(true);return}
    const previousDeadline=a.sectionDeadline;
    a.sectionIndex++;a.itemIndex=0;
    a.sectionDeadline=(expired?previousDeadline:Date.now())+a.exam.sections[a.sectionIndex].duration_seconds*1000;
  }while(expired&&Date.now()>=a.sectionDeadline);
  saveAttempt();renderRunner();
  if(expired)toast('Section time ended. Your entered responses were retained.');
}

async function submitAttempt(confirmed:boolean){if(!active||busy)return;if(!confirmed&&!await confirmDialog('Ready to review your work?','Unanswered tasks will remain blank. Your result will show practice points and separate writing/speaking guidance.','Finish & review'))return;if(recordingItem){toast('Stop your recording before submitting.');return}busy=true;const a=active;const payload:Submission={exam_id:a.exam.id,exam_version:a.exam.version,attempt_id:a.id,answers:a.answers,elapsed_seconds:Math.min(604800,Math.max(0,Math.floor((Date.now()-a.startedAt)/1000))),completed_sections:a.completed,assisted:a.assisted};try{const envelope=a.offline?offlineComplete(a.exam,payload):await api<Envelope>('complete',payload as unknown as Record<string,unknown>,'POST');lastEnvelope=envelope;const history=localHistory();history.unshift({date:Date.now(),envelope});write(`history:${scope()}`,JSON.stringify(history.slice(0,20)));write(`attempt:${scope()}`,'null');stopClock();active=null;const main=shell();renderResult(main,envelope,a);window.scrollTo(0,0)}catch(e){saveAttempt();toast(errorText(e))}finally{busy=false}}
function renderResult(main:HTMLElement,envelope:Envelope,attempt?:Attempt){const r=envelope.result;if(envelope.mock_access)access=envelope.mock_access as Access;const context=attempt||resultContext(r);main.append(button('← Back to practice',()=>{navigate('practice')},'text-button'),heading('EVERY ATTEMPT HAS SOMETHING TO TEACH YOU','Your effort, a little clearer.',r.name));const score=h('div','result-score');score.append(h('strong','',r.objective_total?`${r.objective_score} / ${r.objective_total}`:'Writing & speaking'),text(r.objective_total?'Objective practice points':'No automatic objective score'));main.append(score,notice(envelope.saved?'Saved to your NISHA account.':'Saved only on this phone. This is not an account-saved result.'));if(r.content_source==='generated'||attempt?.offline)main.append(text('Generated practice · Not teacher-reviewed. Scores are learning guidance, not official IELTS or PTE results.','fine-print'));for(const review of r.review||[]){const details=h('details','review-card');details.append(h('summary','',review.prompt||review.title||review.id));const body=h('div','review-body');body.append(text(`Your response: ${displayAnswer(review.response)}`));body.append(feedbackPanel(review));if(['essay','spoken'].includes(review.type)){const saved=(envelope.ai_reviews as any[]|undefined)?.find(entry=>entry.item_id===review.id);if(saved?.review){const feedback=h('section','ai-panel');feedback.append(h('h3','','Saved AI feedback'));showAIFeedback(feedback,saved.review);body.append(feedback)}else{const q=context.exam.sections.flatMap(s=>s.items).find(q=>q.id===review.id);if(q)body.append(aiPanel(q,context,true))}}details.append(body);main.append(details)}main.append(text('Keep useful lessons. Come back for another small step when you are ready.','fine-print'))}
function resultContext(result:Result):Attempt {
  const items=(result.review||[]).map(review=>({...(review.item_snapshot as Item||{}),id:review.id,type:review.type,prompt:review.prompt||review.title||''}));
  const exam:Exam={id:result.exam_id,name:result.name,exam:result.exam,version:result.exam_version||'',session_type:result.session_type||'full',timing_mode:'untimed',resources:result.resources||{},sections:[{id:'review',title:'Saved review',duration_seconds:0,navigation:'free',items}]};
  return {exam,id:result.attempt_id||'',answers:result.responses||{},sectionIndex:0,itemIndex:0,startedAt:Date.now(),sectionDeadline:0,completed:[],offline:result.offline===true,assisted:true,scope:scope(),expiresAt:Date.now()+48*3600*1000,itemDeadlines:{}};
}
function clearDeviceCopies() {
  write(`attempt:${scope()}`,'null');write(`history:${scope()}`,'[]');
  try{for(const key of Object.keys(localStorage))if(key.startsWith(`nisha-mobile:ai-pending:${scope()}:`))localStorage.removeItem(key)}catch{}
  discardMedia();
}
function aiPanel(q:Item,a:Attempt,finished=false) {
  const p=h('section','ai-panel');
  p.append(h('h3','','A little guidance from AI.'),text('Get a practice estimate, useful examples and a plan to improve. Speaking reviews assess language in the transcript, not pronunciation or delivery.','fine-print'));
  if(a.offline){p.append(notice('This task is available offline. AI review is available for online guided practice and saved online tests when connected.'));return p}
  if(!user){p.append(button('Sign in for AI coaching',()=>navigate('account'),'button outline'));return p}
  const key=`${a.id}:${q.id}`;
  const storageReference=`ai-pending:${a.scope}:${key}`;
  let pending=read(storageReference);
  const clip=recordings.get(key);
  const source=q.type==='spoken'&&clip?select({recording:'My recording from this session',transcript:'Transcript of what I said'},'recording'):null;
  if(source){if(maxAudioBytes===0)source.value='transcript';p.append(field('Choose what the AI should review',source),text(maxAudioBytes===0?'Recording uploads are unavailable on the website right now. Your recording remains on this phone; enter a transcript for AI language feedback.':'Choosing the recording sends it to NISHA and OpenAI only when you press review.','fine-print'))}
  const status=text('AI feedback uses your account’s daily review allowance. No request is sent until you choose review.','fine-print');
  status.setAttribute('role','status');const result=h('div','ai-feedback');
  const run=button('Review my answer',async()=>{
    const response=typeof a.answers[q.id]==='string'?a.answers[q.id] as string:'';
    const useAudio=source?.value==='recording'&&clip;
    if(!useAudio&&!response.trim()){status.textContent='Enter your response or an accurate transcript first.';return}
    if(useAudio){
      const padding=clip.base64.endsWith('==')?2:clip.base64.endsWith('=')?1:0;
      const bytes=Math.max(0,Math.floor(clip.base64.length*3/4)-padding);
      if(maxAudioBytes===0){status.textContent='Recording uploads are unavailable on the website right now. Your recording is kept on this phone. Choose a transcript for AI feedback.';return}
      if(bytes>maxAudioBytes){status.textContent='This recording exceeds the website’s current upload limit. Your recording is kept on this phone. Record a shorter answer or choose a transcript for AI feedback.';return}
    }
    pending||=newReference();write(storageReference,pending);
    run.disabled=true;if(source)source.disabled=true;status.textContent=useAudio?'Uploading your selected recording for AI feedback…':'Preparing your feedback…';
    try{
      const fields:Record<string,string>={request_id:pending,exam_id:a.exam.id,exam_version:a.exam.version,item_id:q.id,attempt_id:a.id,response};
      let payload:Record<string,unknown>|FormData=fields;
      if(useAudio){
        const binary=atob(clip.base64);const bytes=Uint8Array.from(binary,char=>char.charCodeAt(0));
        if(bytes.length>maxAudioBytes)throw new Error('This recording exceeds the website’s current upload limit. Your recording is kept on this phone; choose a transcript for AI feedback.');
        const form=new FormData();for(const [name,value]of Object.entries(fields))form.append(name,value);
        form.append('audio',new Blob([bytes],{type:'audio/wav'}),'nisha-speaking.wav');payload=form;
      }else if(q.type==='spoken')fields.transcript=response;
      const reply=await api<any>('ai_review',payload,'POST');
      showAIFeedback(result,reply.review||reply.entry?.review);status.textContent='Your AI practice feedback is ready.';pending='';write(storageReference,'');recovery.hidden=true;newReview.hidden=true;
    }catch(e){status.textContent=errorText(e);recovery.hidden=false;newReview.hidden=false}
    finally{run.disabled=false;if(source)source.disabled=false}
  },'button');
  const recovery=button('Check my pending review',async()=>{
    if(!pending)return;
    try{
      const reply=await api<any>('ai_status',{request_id:pending});
      if(reply.state==='completed'||reply.review||reply.entry?.review){showAIFeedback(result,reply.review||reply.entry?.review);status.textContent='Saved feedback recovered.';pending='';write(storageReference,'');recovery.hidden=true;newReview.hidden=true}
      else status.textContent=reply.state==='pending'?'Your review is still being prepared. Check again shortly.':'No completed feedback was found for this reference. Your response is retained.';
    }catch(e){status.textContent=errorText(e)}
  },'text-button');
  const newReview=button('Start a new review reference',async()=>{
    if(await confirmDialog('Start another review?','Check pending feedback first. A new review can use another request from your daily allowance.','Use a new reference')){pending='';write(storageReference,'');recovery.hidden=true;newReview.hidden=true;status.textContent='A new reference is ready. Press review when you want to send the current response.'}
  },'text-button');
  recovery.hidden=!pending;newReview.hidden=!pending;p.append(run,recovery,newReview,status,result);
  if(!finished&&a.exam.session_type!=='practice'){run.disabled=true;status.textContent='Finish and save this timed test before requesting AI feedback.'}
  return p;
}

function showAIFeedback(container:HTMLElement,review:any){container.replaceChildren();if(!review){container.append(notice('This feedback is not available yet.'));return}if(review.score){const value=typeof review.score==='object'?review.score.value:review.score;if(value!==null&&value!==undefined)container.append(h('h4','',`Practice estimate: ${value}${review.score.scale?` · ${review.score.scale}`:''}`))}if(review.summary)container.append(text(String(review.summary)));for(const field of ['strengths','improvements','next_steps','limitations'])if(Array.isArray(review[field])){container.append(h('h4','',field.replaceAll('_',' ')));const list=h('ul');review[field].forEach((v:unknown)=>list.append(h('li','',typeof v==='string'?v:displayAnswer(v))));container.append(list)}if(review.improved_sample){const details=h('details');details.append(h('summary','','Learning example'),text(String(review.improved_sample)));container.append(details)}}
function localHistory():{date:number;envelope:Envelope}[]{try{return JSON.parse(read(`history:${scope()}`,'[]'))}catch{return []}}
function renderAccount(main:HTMLElement){main.append(heading(user?'YOUR PROGRESS HAS A HOME':'A LITTLE SUPPORT. A BIGGER FUTURE.',user?'Your NISHA account.':'Welcome to your next chapter.',user?'Your practice and learning, in one place.':'Sign in to save online results and continue across devices. Offline practice is always here.'));if(!user){renderAuth(main);const history=panel('Practice on this phone.','Your offline results stay on this device without an account.');for(const entry of localHistory()){const row=button(entry.envelope.result.name,()=>{lastEnvelope=entry.envelope;render()},'history-row');history.append(row)}history.append(button('Clear guest device copies',async()=>{if(await confirmDialog('Clear guest practice?','This removes guest text drafts, local results and recordings from this phone.','Clear guest copies')){clearDeviceCopies();render()}},'button outline'));main.append(history);return}const profile=panel(user.name,user.email);profile.append(text(access?.paid_active?`Full mock pass active${access.paid_until?` until ${access.paid_until} UTC`:''}.`:'Your account includes one free full mock. Existing access passes are recognised when connected.'));profile.append(button('Refresh account',()=>void refreshAccount(),'button outline'),button('Sign out',()=>void logout(),'text-button'));main.append(profile);const history=panel('A record of your effort.','Recent practice saved on this phone.');const local=localHistory();if(!local.length)history.append(text('Your first result will appear here after a practice session.','muted'));for(const entry of local){const b=button('',()=>{lastEnvelope=entry.envelope;render()},'history-row');b.append(h('strong','',entry.envelope.result.name),text(`${new Date(entry.date).toLocaleDateString()} · ${entry.envelope.result.objective_score}/${entry.envelope.result.objective_total} points`,'muted'));history.append(b)}history.append(button('Load saved account history',()=>void loadHistory(history),'button outline'));main.append(history);const privacy=panel('Your phone. Your privacy.','Text drafts and local results are separated by account. Recordings are cleared when the app closes.');privacy.append(button('Clear this account’s device copies',async()=>{if(await confirmDialog('Clear device copies?','This removes local text drafts and results for this account. Account-saved results remain available online.','Clear device copies')){clearDeviceCopies();render()}},'button outline'),button('Request account deletion',()=>void deleteAccount(),'text-button danger'));main.append(privacy,text('This app provides learning access. Digital purchases are not offered in this build; existing account access continues to work.','fine-print'))}
function renderAuth(main:HTMLElement){const card=panel(authMode==='login'?'A familiar place to return.':'Let’s take the first step.');const modes=h('div','segmented');modes.append(button('Sign in',()=>{authMode='login';render()},'segment'+(authMode==='login'?' active':'')),button('Create account',()=>{authMode='register';render()},'segment'+(authMode==='register'?' active':'')));card.append(modes);const form=h('form','auth-form');const name=input('name');name.autocomplete='name';name.maxLength=100;name.minLength=2;name.required=authMode==='register';if(authMode==='register')form.append(field('Your name',name));const email=input('email','email');email.autocomplete='email';email.maxLength=254;email.required=true;const password=input('password','password');password.autocomplete=authMode==='login'?'current-password':'new-password';password.minLength=authMode==='login'?1:8;password.required=true;form.append(field('Email address',email),field('Password',password));const confirmation=input('password_confirmation','password');confirmation.autocomplete='new-password';confirmation.required=authMode==='register';if(authMode==='register')form.append(field('Confirm password',confirmation));const status=text('','form-status');status.setAttribute('role','status');const submit=h('button','button',authMode==='login'?'Sign in →':'Create my account →');submit.type='submit';form.append(submit,status);form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;status.textContent='Opening your account…';try{user=await authenticate(authMode,{email:email.value.trim(),password:password.value,...(authMode==='register'?{name:name.value.trim(),password_confirmation:confirmation.value}:{})});active=null;password.value='';confirmation.value='';await refreshAccount();render()}catch(error){status.textContent=errorText(error)}finally{submit.disabled=false}};card.append(form);main.append(card,button('Practise offline without an account →',()=>navigate('practice'),'text-button'))}
async function refreshAccount(){try{const reply=await api<{user:User;access?:Access}>('me');user=reply.user;access=reply.access||null;connectionMessage='';render()}catch(e){if(e instanceof ApiError&&e.status===401){user=null;access=null;render()}toast(errorText(e))}}
async function logout(){try{if(hasToken())await api('logout',{},'POST')}catch{}await forgetToken();user=null;access=null;active=null;discardMedia();stopClock();render()}
async function loadHistory(container:HTMLElement){try{const reply=await api<any>('history');const items=reply.items||reply.results||reply.history||[];const old=container.querySelector('.online-history');old?.remove();const list=h('div','online-history');if(!items.length)list.append(text('No account-saved results yet.','muted'));for(const item of items){const b=button('',async()=>{try{const result=await api<Envelope>('result',{id:item.id});lastEnvelope=result;render()}catch(e){toast(errorText(e))}},'history-row');b.append(h('strong','',item.exam_name||item.name||'Saved practice'),text(`${String(item.created_at||'').slice(0,16)} · ${item.objective_score??0}/${item.objective_total??0} points`,'muted'));list.append(b)}container.append(list)}catch(e){toast(errorText(e))}}
async function deleteAccount(){if(!user)return;const dialog=h('dialog','modal');const form=h('form','modal-form');form.append(h('h2','','Request account deletion'),text('This sends a deletion request for the signed-in account and signs this app out. The owner will fulfil it and retain only records required for financial or legal obligations.'));const password=input('password','password');password.autocomplete='current-password';password.required=true;form.append(field('Confirm your current password',password));const confirm=input('confirmation','checkbox');confirm.required=true;const l=h('label','checkbox-label');l.append(confirm,h('span','','I want to request deletion of my NISHA account.'));form.append(l);const status=text('');status.setAttribute('role','status');const actions=h('div','modal-actions');const submit=h('button','button danger','Send deletion request');submit.type='submit';actions.append(button('Keep my account',()=>dialog.close(),'button outline'),submit);form.append(status,actions);form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{await api('deletion_request',{password:password.value,confirmation:true},'POST');password.value='';await forgetToken();user=null;access=null;active=null;stopClock();discardMedia();dialog.close();render();toast('Your deletion request has been recorded. This app is now signed out.')}catch(e){status.textContent=errorText(e);submit.disabled=false}};dialog.append(form);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());openDialog(dialog)}
async function renderCoaching(){const main=document.querySelector('#main');if(tab!=='coaching'||!main)return;main.querySelector('.coaching-content')?.remove();const content=h('div','coaching-content');main.append(content);if(!user){content.append(notice('Sign in to explore NISHA coaching lessons.'),button('Sign in',()=>navigate('account'),'button'));return}const filters=h('form','filters');const query=input('q','search');query.placeholder='Topic, teacher or lesson';const course=select({'':'All courses',...titles},'');const skill=select({'':'All skills',reading:'Reading',listening:'Listening',writing:'Writing',speaking:'Speaking'},'');filters.append(field('Find a lesson',query),field('Course',course),field('Skill',skill));const find=h('button','button','Find lessons');find.type='submit';filters.append(find);const results=h('div','card-list');content.append(filters,results);const load=async()=>{find.disabled=true;results.replaceChildren(notice('Finding your next lesson…'));try{const reply=await api<any>('coaching',{q:query.value,course:course.value,skill:skill.value});const lessons=reply.items||reply.lessons||reply.videos||[];results.replaceChildren();if(!lessons.length)results.append(notice(query.value||course.value||skill.value?'No lessons match this focus. Try clearing the filters.':'No lessons have been published yet. Teachers and the owner need to review and publish lessons first. You can keep learning with practice questions.'));for(const lesson of lessons){const card=h('article','practice-card');card.append(text(`${titles[lesson.course_id]||lesson.course_id} · ${lesson.skill}`,'eyebrow'),h('h3','',lesson.title),text(`With ${lesson.teacher_name||'a NISHA teacher'}`,'muted'),text(lesson.description||''),button('Open lesson →',()=>void openLesson(lesson.id,card),'button outline'));results.append(card)}}catch(e){results.replaceChildren(notice(errorText(e)))}finally{find.disabled=false}};filters.onsubmit=e=>{e.preventDefault();void load()};void load()}
async function openLesson(id:number,card:HTMLElement){try{const reply=await api<any>('lesson',{id});const lesson=reply.lesson||reply.video||reply;const url=lesson.video_url;if(!url){card.append(notice('This lesson needs an active NISHA access pass. Your free practice remains available.'));return}const parsed=new URL(url);if(parsed.protocol!=='https:')throw new Error('This video link is unavailable.');card.querySelector('video')?.remove();const video=h('video');video.controls=true;video.playsInline=true;video.preload='none';video.src=url;video.setAttribute('aria-label',lesson.title||'Coaching lesson');card.append(video);video.addEventListener('error',()=>{if(!card.querySelector('.video-load-error'))card.append(notice('This video could not be loaded. Try your connection again or let NISHA support know about this lesson.','video-load-error'))});let watchToken:string|null=null,lastTick=0;video.addEventListener('play',async()=>{try{const r=await api<any>('watch',{action:'start',video_id:id,position:video.currentTime},'POST');watchToken=r.token||r.watch_token||null}catch{/* Playback remains useful when tracking is unavailable. */}});video.addEventListener('timeupdate',()=>{if(!watchToken||video.paused||document.hidden||Date.now()-lastTick<10000)return;lastTick=Date.now();void api('watch',{action:'heartbeat',video_id:id,token:watchToken,position:video.currentTime,playing:!video.paused&&!video.ended,visible:!document.hidden},'POST').catch(()=>{})})}catch(e){card.append(notice(errorText(e)))}}
function toast(message:string){document.querySelector('.toast')?.remove();const n=h('div','toast',message);n.setAttribute('role','status');n.append(button('×',()=>n.remove(),'toast-close'));document.body.append(n);setTimeout(()=>n.remove(),12000);announce(message)}
function confirmDialog(title:string,message:string,action:string):Promise<boolean>{return new Promise(resolve=>{const d=h('dialog','modal');d.append(h('h2','',title),text(message));const actions=h('div','modal-actions');let answered=false;actions.append(button('Keep working',()=>{answered=true;resolve(false);d.close()},'button outline'),button(action,()=>{answered=true;resolve(true);d.close()},'button'));d.append(actions);document.body.append(d);d.addEventListener('close',()=>{if(!answered)resolve(false);d.remove()});openDialog(d)})}
window.addEventListener('nisha-session-expired',()=>{saveAttempt();active=null;user=null;access=null;stopClock();discardMedia();tab='account';lastEnvelope=null;render();toast('Your account session ended. Sign in again to continue; text drafts were retained for your account.')});
window.addEventListener('beforeunload',()=>saveAttempt());document.addEventListener('visibilitychange',()=>{if(document.hidden){saveAttempt();void stopSpeech();if(recordingItem){void cancelRecording();recordingItem=null}}else updateClocks()});window.addEventListener('offline',()=>{onlineReady=false;connectionMessage='You are offline. Included practice tasks are ready on this phone.';if(!active)render()});
async function boot(){const stored=read('theme');setTheme(stored||((matchMedia('(prefers-color-scheme:dark)').matches)?'dark':'light'));render();try{await initialiseToken();if(hasToken()){const reply=await api<{user:User;access?:Access}>('me');user=reply.user;access=reply.access||null}}catch(e){connectionMessage=errorText(e)}render();void loadOnline(false)}
void boot();
